/// CaptureForm is a multipart body of KUAA's API.
///
/// The initializer takes the required fields first; an optional field left
/// nil is not sent.
public struct CaptureForm: Encodable, Sendable, Hashable {
    /// Optional: when each file was captured, RFC 3339, one per file in the order of the files.
    public var capturedAt: [String]?
    /// Required for a document, refused for anything else.
    public var documentType: CaptureFormDocumentType?
    /// The images, JPEG or PNG, each at most 8 MiB, at least 64 pixels on a side and at most 25 megapixels: up to 2 for a document, 1 for a selfie, up to 32 frames for a liveness capture, in capture order.
    public var file: [FilePart]
    /// What the files are: the sides of a document, one selfie, or the frames of one liveness capture.
    public var kind: CaptureFormKind
    /// The party captured. Empty is the case's primary party.
    public var partyID: String?
    /// Required for a document, refused for anything else.
    public var side: CaptureFormSide?

    public init(file: [FilePart], kind: CaptureFormKind, capturedAt: [String]? = nil, documentType: CaptureFormDocumentType? = nil, partyID: String? = nil, side: CaptureFormSide? = nil) {
        self.capturedAt = capturedAt
        self.documentType = documentType
        self.file = file
        self.kind = kind
        self.partyID = partyID
        self.side = side
    }

    enum CodingKeys: String, CodingKey {
        case capturedAt = "captured_at"
        case documentType = "document_type"
        case file
        case kind
        case partyID = "party_id"
        case side
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encodeIfPresent(capturedAt, forKey: .capturedAt)
        try container.encodeIfPresent(documentType, forKey: .documentType)
        try container.encode(file, forKey: .file)
        try container.encode(kind, forKey: .kind)
        try container.encodeIfPresent(partyID, forKey: .partyID)
        try container.encodeIfPresent(side, forKey: .side)
    }

    /// The form's fields, in the order of the contract: a list as one part
    /// per item.
    func parts() -> [(String, Part)] {
        var parts: [(String, Part)] = []
        parts += (capturedAt ?? []).map { ("captured_at", Part.text($0)) }
        if let documentType = documentType {
            parts.append(("document_type", Part.text(documentType.rawValue)))
        }
        parts += file.map { ("file", Part.file($0)) }
        parts.append(("kind", Part.text(kind.rawValue)))
        if let partyID = partyID {
            parts.append(("party_id", Part.text(partyID)))
        }
        if let side = side {
            parts.append(("side", Part.text(side.rawValue)))
        }
        return parts
    }
}

